// Deterministic staged scenes for Solmar Bay's screenshots. Each scene builds
// a fixed moment of play — a chase, a beach drive, a dockside shootout, a
// walk through the park — from a seeded stream, then settles it with a few
// fixed simulation steps. The screenshots are real frames of the game.

import { streetPos, blockRect, TUNE } from './config.js';
import { landmarkPos } from './world.js';
import { makeCar } from './vehicles.js';
import { makePed } from './pedestrians.js';
import { makeEnemy } from './combat.js';
import { startMission } from './missions.js';

function settle(G, steps = 50) {
  for (let i = 0; i < steps; i++) G.stepWorld(1 / 60);
}

function placeTraffic(G, spots) {
  for (const s of spots) {
    const car = makeCar(s.x, s.y, s.angle, s.color, 'traffic');
    car.speed = s.speed ?? 150;
    car.ai = { axis: s.axis, dir: s.dir, turnCooldown: 2, wantTurn: false };
    G.cars.push(car);
  }
}

function placePeds(G, spots) {
  for (const s of spots) {
    const ped = makePed(G, s.x, s.y);
    ped.axis = s.axis || 'h';
    ped.dir = s.dir || 1;
    ped.speed = s.speed ?? 55;
    G.peds.push(ped);
  }
}

